import { useState, useEffect, useMemo } from 'react';
import axios from 'axios';

interface Clinic {
  id: number;
  name: string;
  address: string;
  hotline: string;
  total_chairs?: number;
  map_url?: string;
}

interface Service {
  id: number;
  name: string;
  category: string;
  duration_minutes: number;
}

interface PatientForm {
  fullName: string;
  phone: string;
  email: string;
  dob: string;
  service: number | '';
}

interface MatrixChair {
  chair: number;
  status: 'available' | 'booked';
  booking_id: number | null;
  customer_name: string | null;
  service_name: string | null;
}

interface MatrixRow {
  time: string;
  start_time: string;
  chairs: MatrixChair[];
}

